import Ajv from "ajv";
import dagre from "dagre";
import deepEqual from "fast-deep-equal";
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

//#region 🧬️LanguageNeutralContract

const editorRoot = new URL("../../", import.meta.url);
/** 🔤️ The Rust variant name of one kebab lane/disposition from `framework.ui`'s shared vocabulary. */
const variant = (value) => value.split("-").map((part) => `${part[0].toUpperCase()}${part.slice(1)}`).join("");

const module = JSON.parse(readFileSync(fileURLToPath(new URL("../../🧬️schema/🔣️.json", editorRoot)), "utf8"));
const fixture = JSON.parse(readFileSync(fileURLToPath(new URL("🧫️fixtures/📌️retained-actions/🔣️.json", editorRoot)), "utf8"));
const source = readFileSync(fileURLToPath(new URL("../🦀️.rs", editorRoot)), "utf8");
const ajv = new Ajv({ strict: true });
ajv.addKeyword({ keyword: "x-semio-state", metaSchema: { type: "string" } });
ajv.addKeyword({ keyword: "x-semio-formats", metaSchema: { type: "array", items: { type: "string" } } });
for (const numeric of ["double", "float", "int32", "int64", "uint32", "uint64"]) ajv.addFormat(numeric, true);
const validate = ajv.compile({ $defs: module.$defs, $ref: "#/$defs/SequenceRetainedActions" });

if (!validate(fixture)) throw new Error(`Sequence retained action fixture rejected: ${JSON.stringify(validate.errors)}`);
const ids = fixture.routes.map(({ id }) => id);
if (new Set(ids).size !== 16) throw new Error("Sequence retained action fixture must own 16 unique live routes");

for (const route of fixture.routes) {
  const declaration = `.action_interactive_job("${route.id}", semio_framework_plugin::InteractiveJobClassification::${variant(route.classification)})`;
  if (!source.includes(declaration)) throw new Error(`Sequence source classification drifted for ${route.id}`);
}

const migrated = fixture.routes.filter(({ classification }) => classification === "migrated");
const pending = fixture.routes.filter(({ classification }) => classification === "batch-only-pending-rewrite");
if (migrated.length !== 16 || pending.length !== 0) throw new Error("Sequence retained route disposition counts drifted");
for (const route of migrated) {
  if (!source.includes(`tool_id: "${route.id}", lanes: &[semio_framework_plugin::ArtifactToolPublicationLane::${variant(route.publicationLane)}]`)) throw new Error(`Sequence publication lane drifted for ${route.id}`);
  const persistent = route.contract.maximumUnits === 66049;
  const maximumUnits = persistent ? "66_049" : "2";
  const outputBytes = route.publicationLane === "child" || route.id === "run" ? "65_536" : "4_096";
  const maximumStepMicros = persistent ? "7_500" : "2_000";
  if (!source.includes(`"${route.id}" => semio_framework::ToolExecutionContract::resumable(4_096, ${maximumUnits}, 1, ${outputBytes}, ${maximumStepMicros}, 1, 1)`)) throw new Error(`Sequence bounded proof drifted for ${route.id}`);
}

for (const law of hostileLaws(fixture)) {
  if (validate(law.value)) throw new Error(`Sequence hostile schema law was accepted: ${law.id}`);
}

for (const token of ["ArtifactCommandWorkStep::Progress", "ArtifactCommandWorkStep::Replay", "fn checkpoint", "fn restore", "fn begin_close", "fn close_step", "fn terminal_is_empty"]) {
  if (!source.includes(token)) throw new Error(`Sequence retained state-machine law is missing ${token}`);
}
for (const token of ["fn build_artifact_store_one_item_preparation_factory()", "SequenceArtifactStorePreparationFactory", "canonical_base_revision: request.canonical_base_revision"]) {
  if (!source.includes(token)) throw new Error(`Sequence retained Store/freshness authority is missing ${token}`);
}
const windowConfigSource = readFileSync(fileURLToPath(new URL("../🎭️modes/✏️edit/🪟️windows/📽️main/🎚️config/🦀️.rs", editorRoot)), "utf8");
for (const token of ["impl semio_framework_plugin::WindowConfigOwner for SequenceMainWindowConfigOwner", "fn build_one_item_preparation_factory()", "bounded_window_config_preparation_factory::<Self>()"]) {
  if (!windowConfigSource.includes(token)) throw new Error(`Sequence retained WindowConfig authority is missing ${token}`);
}
for (const token of ["SequenceReorganizeState", "self.edge += 1", "SequenceNodeGraphStage::FixtureSteps", "self.fixture_steps.pop_front()", "SequenceNodeGraphStage::DeleteSelectionDiscover", "self.delete_scan += 1", "self.operation += 1", "SequenceRunOrderStage", "frame.order.advance", "sequence-run-retire-frame", "sequence-persistent-publication-lane", "maximum_items == 0 || maximum_bytes == 0"]) {
  if (!source.includes(token)) throw new Error(`Sequence persistent cursor law is missing ${token}`);
}
const reorganizeOracle = dagreLayoutOracle(fixture.persistentOracle.reorganize);
if (!deepEqual(reorganizeOracle, fixture.persistentOracle.reorganize.expected)) throw new Error(`Sequence reorganize fixture drifted from dagre: ${JSON.stringify(reorganizeOracle)}`);
const nodeGraphOracle = nodeGraphMutationOracle(fixture.persistentOracle.nodeGraphEdit);
if (!deepEqual(nodeGraphOracle, fixture.persistentOracle.nodeGraphEdit.expectedMutations)) throw new Error(`Sequence node-graph fixture drifted: ${JSON.stringify(nodeGraphOracle)}`);
const runOracle = graphOrderOracle(fixture.persistentOracle.run);
if (!deepEqual(runOracle, fixture.persistentOracle.run.expectedOrder)) throw new Error(`Sequence run order drifted from graphlib: ${JSON.stringify(runOracle)}`);

console.log(JSON.stringify({ oracle: "ajv-draft07+dagre-0.8.5+graphlib", routes: ids.length, migrated: migrated.length, pending: pending.length, hostileLaws: 9, persistentScenarios: 3, maximumStepMicros: fixture.runtimeLaws.maximumStepMicros, locales: fixture.locales, accessibility: "bounded-progress-cancel-close", customization: Object.keys(fixture.customization) }));

//#endregion 🧬️LanguageNeutralContract

//#region 🧭️ThirdPartyOracles

function graph(scenario) {
  const value = new dagre.graphlib.Graph({ directed: true }).setGraph({ rankdir: "LR", ranksep: 280, nodesep: 160, marginx: 0, marginy: 0 }).setDefaultEdgeLabel(() => ({}));
  for (const id of scenario.nodes) value.setNode(id, { width: 0, height: 0 });
  for (const [from, to] of scenario.edges) value.setEdge(from, to);
  return value;
}

function dagreLayoutOracle(scenario) {
  const value = graph(scenario);
  dagre.layout(value);
  return scenario.nodes.map((id) => ({ id, x: value.node(id).x, y: value.node(id).y }));
}

function graphOrderOracle(scenario) {
  return dagre.graphlib.alg.topsort(graph(scenario));
}

function nodeGraphMutationOracle(scenario) {
  const deleted = scenario.baseSteps.filter((step) => !scenario.targetSteps.some((target) => target.id === step.id)).map((step) => step.id);
  const recreated = scenario.targetSteps.filter((step) => scenario.baseSteps.some((base) => base.id === step.id && base.kind !== step.kind)).map((step) => step.id);
  const mutations = deleted.map((id) => `DeleteStep:${id}`);
  for (const step of scenario.targetSteps) {
    if (recreated.includes(step.id)) mutations.push(`DeleteStep:${step.id}`, `CreateStep:${step.id}`);
    else if (!scenario.baseSteps.some((base) => base.id === step.id)) mutations.push(`CreateStep:${step.id}`);
  }
  for (const edge of scenario.baseEdges) {
    if (![...deleted, ...recreated].includes(edge.from) && ![...deleted, ...recreated].includes(edge.to) && !scenario.targetEdges.some((target) => target.id === edge.id)) mutations.push(`DisconnectSteps:${edge.id}`);
  }
  for (const edge of scenario.targetEdges) {
    if (![...scenario.baseEdges.map(({ id }) => id)].includes(edge.id) || recreated.includes(edge.from) || recreated.includes(edge.to)) mutations.push(`ConnectSteps:${edge.id}`);
  }
  return mutations;
}

//#endregion 🧭️ThirdPartyOracles

//#region ☣️HostileLaws

function hostileLaws(valid) {
  const unknown = structuredClone(valid);
  unknown.routes[0].identityCache = true;
  const falseMigrated = structuredClone(valid);
  falseMigrated.routes[0].classification = "MigratedWithoutCursor";
  const falseBatch = structuredClone(valid);
  falseBatch.routes[0].classification = "batch-only-pending-rewrite";
  const oversized = structuredClone(valid);
  oversized.routes.find(({ classification }) => classification === "migrated").contract.maximumRawBytes = 4097;
  const excessiveUnits = structuredClone(valid);
  excessiveUnits.routes.find(({ contract }) => contract.maximumUnits === 66049).contract.maximumUnits = 66050;
  const monolingual = structuredClone(valid);
  monolingual.locales = ["en"];
  const slowPoll = structuredClone(valid);
  slowPoll.runtimeLaws.maximumStepMicros = 8001;
  const wrongChildLane = structuredClone(valid);
  wrongChildLane.routes.find(({ id }) => id === "addStep").publicationLane = "window-config";
  const wrongTransientLane = structuredClone(valid);
  wrongTransientLane.routes.find(({ id }) => id === "run").publicationLane = "child";
  return [
    { id: "wrong-child-publication-owner", value: wrongChildLane },
    { id: "wrong-transient-publication-owner", value: wrongTransientLane },
    { id: "unknown-property", value: unknown },
    { id: "false-migrated", value: falseMigrated },
    { id: "false-batch-contract", value: falseBatch },
    { id: "oversized-wire", value: oversized },
    { id: "excessive-units", value: excessiveUnits },
    { id: "monolingual", value: monolingual },
    { id: "slow-poll", value: slowPoll },
  ];
}

//#endregion ☣️HostileLaws

import Ajv2020 from "ajv/dist/2020.js";
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { createSequenceBrowserFeatures } from "@semio-tech/sequence-sequence";

//#region 🔮️ThirdPartyOracle

const root = new URL("../../🏅️standards/🔖️1/🪆️subsets/✳️any/✏️editor/🌉️wasm/", import.meta.url);
const schema = JSON.parse(readFileSync(fileURLToPath(new URL("🧬️schema/🔣️.json", root)), "utf8"));
const fixture = JSON.parse(readFileSync(fileURLToPath(new URL("🧫️fixtures/🔣️.json", root)), "utf8"));
const oracle = createOraclePort(new Ajv2020({ strict: true }).compile(schema));
const expected = oracle.emit(fixture);

//#endregion 🔮️ThirdPartyOracle

//#region 🧩️OwnedFeature

const memory = new WebAssembly.Memory({ initial: 2 });
const bridge = new CaptureBridge(memory);
const features = await createSequenceBrowserFeatures({ source: Uint8Array.of(0, 97, 115, 109), instantiate: async () => ({ instance: { exports: { ...bridge.exports, memory } } }) });
const task = features.editing.addStepDropped(fixture.input.kind, fixture.input.x, fixture.input.y, fixture.input.picked);
const semantic = await task.result;

if (bridge.frameHex !== expected.frameHex) throw new Error("Sequence owned feature and third-party oracle protocol frames differ");
if (semantic !== expected.semantic) throw new Error("Sequence owned feature and third-party oracle semantic results differ");
await features.lifetime.close();

console.log(JSON.stringify({ oracle: "ajv-test-only", interface: "owned", feature: expected.feature, protocol: "equal", semantic: "equal" }));

//#endregion 🧩️OwnedFeature

//#region 🧪️OraclePort

function createOraclePort(validate) {
  return {
    emit(value) {
      if (!validate(value)) throw new Error("Sequence oracle fixture rejected");
      return { feature: value.feature, frameHex: encodeOracleRequest(value), semantic: value.semantic };
    },
  };
}

function encodeOracleRequest(value) {
  const text = new TextEncoder().encode(value.input.kind);
  const payloadLength = 4 + text.length + 8 + 8 + 1;
  const bodyLength = 8 + payloadLength;
  const bytes = new Uint8Array(20 + bodyLength);
  const view = new DataView(bytes.buffer);
  view.setUint8(0, 1);
  view.setUint8(1, 1);
  view.setUint16(2, value.operation, true);
  view.setBigUint64(4, BigInt(value.requestId), true);
  view.setUint32(12, value.generation, true);
  view.setUint32(16, bodyLength, true);
  view.setUint32(20, value.session.slot, true);
  view.setUint32(24, value.session.generation, true);
  view.setUint32(28, text.length, true);
  bytes.set(text, 32);
  let cursor = 32 + text.length;
  view.setFloat64(cursor, value.input.x, true);
  cursor += 8;
  view.setFloat64(cursor, value.input.y, true);
  cursor += 8;
  view.setUint8(cursor, 0);
  return hex(bytes);
}

//#endregion 🧪️OraclePort

//#region 🌉️CaptureBridge

function CaptureBridge(targetMemory) {
  let cursor = 8;
  let outbound;
  let terminal = false;
  this.frameHex = undefined;
  this.exports = {
    sequence_bridge_create() { return 1; },
    sequence_bridge_destroy() { return 1; },
    sequence_bridge_allocate(length) { const pointer = cursor; cursor += Math.max(1, length); return pointer; },
    sequence_bridge_release() {},
    sequence_bridge_send: (_owner, pointer, length) => {
      const bytes = new Uint8Array(targetMemory.buffer, pointer, length).slice();
      const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
      if (view.getUint8(0) !== 1) return -1;
      if (view.getUint8(1) === 5) return 1;
      if (view.getUint8(1) !== 1) return -1;
      const operation = view.getUint16(2, true);
      const requestId = view.getBigUint64(4, true);
      const generation = view.getUint32(12, true);
      if (operation === 2300) outbound = reply(requestId, generation, handle(1, 1));
      else if (operation === 2305) {
        this.frameHex = hex(bytes);
        outbound = reply(requestId, generation, new TextEncoder().encode("step-101"));
      } else return -1;
      return 1;
    },
    sequence_bridge_poll(_owner, pointer, capacity) {
      if (!outbound) return terminal ? -1 : 0;
      if (outbound.length > capacity) return outbound.length;
      new Uint8Array(targetMemory.buffer, pointer, outbound.length).set(outbound);
      const length = outbound.length;
      outbound = undefined;
      return length;
    },
    sequence_bridge_begin_close() { terminal = true; },
    sequence_bridge_terminal_is_empty() { return Number(terminal); },
  };
}

function reply(requestId, generation, body) {
  const bytes = new Uint8Array(21 + body.length);
  const view = new DataView(bytes.buffer);
  view.setUint8(0, 1);
  view.setUint8(1, 2);
  view.setBigUint64(2, requestId, true);
  view.setUint32(10, generation, true);
  view.setUint16(14, 0, true);
  view.setUint8(16, 0);
  view.setUint32(17, body.length, true);
  bytes.set(body, 21);
  return bytes;
}

function handle(slot, generation) {
  const bytes = new Uint8Array(8);
  const view = new DataView(bytes.buffer);
  view.setUint32(0, slot, true);
  view.setUint32(4, generation, true);
  return bytes;
}

function hex(bytes) { return [...bytes].map((value) => value.toString(16).padStart(2, "0")).join(""); }

//#endregion 🌉️CaptureBridge

import { existsSync } from "node:fs";
import { dirname, join } from "node:path";
